"""Grammars for the free-text kinds that used to be short flat lists.

Business notes, survey feedback, churn, return, cancellation and audit
reasons, delivery instructions, bank statement descriptors, chief complaints,
clinical notes, discharge instructions, social captions, blog post titles and
bodies, and email subjects. Each kind is a grammar (using the inline
``((a|b))`` and ``[[optional]]`` sugar of :class:`misata.microtext.Grammar`)
over per-row slots: names, dates, amounts, places, products, plans. Then
:func:`misata.paraphrase.vary` adds the word-level variation of its register.

A flat list of twelve sentences gave 2,000 rows twelve distinct values and a
gzip ratio of 50; these keep repeats to the rate people's writing has, and
condition on the row where the row says something (a survey score, a
ticket's issue).
"""
from __future__ import annotations

import re
from typing import Dict, List, Optional, Sequence

import numpy as np

from misata.microtext import Grammar, MicrotextGenerator
from misata.paraphrase import vary, vary_keeping

