_BIO_FACETS = ("bio_loc", "bio_int", "bio_int", "bio_pet", "bio_quip", "bio_hist", "bio_learn")
_BIO_SEPS = (". ", " | ", " · ", " / ", " • ", ". ", " | ", " ✨ ", " 🌱 ", " - ")


def _facet_bio(g: Grammar, rng: np.random.Generator, s: Dict[str, str]) -> str:
    """A profile bio as people write them: a few facts in any order."""
    k = int(rng.choice([1, 2, 2, 3, 3, 3, 4]))
    picks = [str(f) for f in rng.choice(_BIO_FACETS, size=k, replace=False)]
    if rng.random() < 0.7:
        picks.insert(int(rng.integers(0, 2)) if rng.random() < 0.3 else 0, "bio_job")
    parts = [g.expand(f, **s) for f in picks]
    sep = _BIO_SEPS[int(rng.integers(len(_BIO_SEPS)))]
    text = sep.join(parts)
    return text + "." if sep == ". " and rng.random() < 0.6 else text


