_ARTICLE = re.compile(r"^(a|an) ")


def _case_slots(rng: np.random.Generator, slots: List[Dict[str, str]]) -> None:
    """One clinical case per row, so the complaint, findings, diagnosis,
    medicines and advice in a note agree with each other."""
    for s in slots:
        dx, symptoms, meds, exams, plans, advice, flags, tests = _CASES[int(rng.integers(len(_CASES)))]
        sy = [symptoms[int(i)] for i in rng.choice(len(symptoms), size=2, replace=False)]
        md = [meds[int(i)] for i in rng.choice(len(meds), size=min(2, len(meds)), replace=False)]
        md2 = md[1] if len(md) > 1 else md[0]
        adv = [advice[int(i)] for i in rng.permutation(len(advice))]
        first = _ARTICLE.sub("", sy[0])
        s.update(dx=dx, dx_cap=dx[0].upper() + dx[1:], symptom_l=first, symptom=first[0].upper() + first[1:],
                 symptom2=sy[1], med=md[0][0], dose=md[0][1], dose_oral=md[0][1], med2=md2[0], dose2=md2[1],
                 cs_exam=exams[int(rng.integers(len(exams)))], cs_plan=plans[int(rng.integers(len(plans)))],
                 cs_adv=adv[0], cs_adv2=adv[1], cs_adv3=adv[-1], cs_adv_cap=adv[0][0].upper() + adv[0][1:],
                 cs_flag=flags[0], cs_flag2=flags[1], cs_test=tests[int(rng.integers(len(tests)))])


