def _product_slots(rng: np.random.Generator, slots: List[Dict[str, str]]) -> None:
    """Feedback about one product: its features, integrations and users."""
    def cap(x):
        return x[0].upper() + x[1:]
    for s in slots:
        kind, feats, ints, roles, wins, pains = _PRODUCTS[int(rng.integers(len(_PRODUCTS)))]
        f1, f2 = (feats[int(i)] for i in rng.choice(len(feats), size=2, replace=False))
        win = wins[int(rng.integers(len(wins)))]
        s.update(pp_kind=kind, pp_feat_l=f1, pp_feat=cap(f1), pp_feat2_l=f2, pp_feat2=cap(f2),
                 pp_int=ints[int(rng.integers(len(ints)))], pp_role=roles[int(rng.integers(len(roles)))],
                 pp_win=win, pp_win_cap=cap(win), pp_pain=pains[int(rng.integers(len(pains)))])
        s["pp_pain_cap"] = cap(s["pp_pain"])
        if rng.random() < 0.7:
            s.update(fb_area=cap(f1), fb_area_l=f1, fb_area2=cap(f2))


