_SLOT_RE = re.compile(r"\{([a-z0-9_]+)\}")


def _home_slots(g: Grammar, rng: np.random.Generator, slots: List[Dict[str, str]]) -> None:
    """One place per delivery: its access, safe spots and quirks agree."""
    for s in slots:
        place, access, spots, quirks = _HOMES[int(rng.integers(len(_HOMES)))]
        sp = [spots[int(i)] for i in rng.choice(len(spots), size=2, replace=False)]
        fill = lambda x: _SLOT_RE.sub(lambda m: s.get(m.group(1)) or g.expand(m.group(1), **s), x)
        s.update(hm_place=place, hm_access=fill(access[int(rng.integers(len(access)))]),
                 hm_spot=fill(sp[0]), hm_spot2=fill(sp[1]), hm_quirk=fill(quirks[int(rng.integers(len(quirks)))]))
        s["hm_place_cap"] = place[0].upper() + place[1:]
        s["hm_quirk_cap"] = s["hm_quirk"][0].upper() + s["hm_quirk"][1:]


_NOUN_FAMILY: Optional[Dict[str, str]] = None


def _family_of(item: str) -> Optional[str]:
    """The review family ("clothing", "electronics" ...) a catalogue noun belongs to."""
    global _NOUN_FAMILY
    if _NOUN_FAMILY is None:
        from misata.scenarios import PRODUCT_FAMILIES, _soft_lower
        _NOUN_FAMILY = {}
        for key, fam in PRODUCT_FAMILIES.items():
            for n in fam.nouns:
                _NOUN_FAMILY.setdefault(_soft_lower(n), key)
    return _NOUN_FAMILY.get(item)


def _product_faults(rng: np.random.Generator, out: List[str], slots: List[Dict[str, str]],
                    share: float) -> List[str]:
    """Swap a share of return reasons for the fault a buyer of that kind of
    product actually reports ("Shrank a whole size after one wash")."""
    from misata.microtext import _FAMILY_LINES
    fam_g = Grammar(_FAMILY_LINES, rng)
    res = []
    for o, s in zip(out, slots):
        fam = _family_of(s.get("item", ""))
        if fam and f"neg_{fam}" in _FAMILY_LINES and rng.random() < share:
            line = fam_g.expand(f"neg_{fam}", **s).rstrip(".")
            o = line if rng.random() < 0.5 else f"{line} - {o[0].lower() + o[1:]}"
        res.append(o)
    return res


