def _booking_slots(g: Grammar, rng: np.random.Generator, slots: List[Dict[str, str]]) -> None:
    """One cancelled booking per row, with reasons and asks that fit it."""
    for s in slots:
        thing, reasons, asks = _BOOKINGS[int(rng.integers(len(_BOOKINGS)))]
        fill = lambda x: _SLOT_RE.sub(lambda m: s.get(m.group(1)) or g.expand(m.group(1), **s), x)
        r = [reasons[int(i)] for i in rng.choice(len(reasons), size=2, replace=False)]
        s.update(bk_thing=fill(thing), bk_reason=fill(r[0]), bk_reason2=fill(r[1]),
                 bk_reason_cap=fill(r[0][0].upper() + r[0][1:]), bk_ask=fill(asks[int(rng.integers(len(asks)))]))
        s["bk_ask_cap"] = s["bk_ask"][0].upper() + s["bk_ask"][1:]


_TIDY_SPACE = re.compile(r" {2,}")
_DOUBLE_STOP = re.compile(r"(?<=\w\.)\.(?!\.)")
_TIDY_COMMA = re.compile(r" +,")


def _topic_slots(rng: np.random.Generator, slots: List[Dict[str, str]],
                 titles: Optional[Sequence] = None) -> None:
    """One topic per post: the title, the body and every sentence in it talk
    about the same thing, in that topic's own words."""
    def pick(pool, k):
        idx = rng.choice(len(pool), size=min(k, len(pool)), replace=False)
        return [pool[int(i)] for i in idx]
    for i, s in enumerate(slots):
        t = None
        title = str(titles[i]).lower() if titles is not None and i < len(titles) else ""
        if title:
            hits = [k for k, tp in enumerate(_POST_TOPICS) if tp[0].split("{")[0].strip().lower() in title]
            t = _POST_TOPICS[hits[0]] if hits else None
        if t is None:
            t = _POST_TOPICS[int(rng.integers(len(_POST_TOPICS)))]
        obj, vs, terms, acts, wins, pains = t
        city = s.get("city", "London")
        fix = lambda x: x.replace("{city}", city)
        terms, acts = pick(terms, 3), pick(acts, 2)
        pi = int(rng.integers(len(pains)))
        s.update(pt_obj=fix(obj), pt_obj_cap=fix(obj[0].upper() + obj[1:]), pt_vs=fix(vs),
                 tp_term=fix(terms[0]), tp_term_cap=fix(terms[0][0].upper() + terms[0][1:]), tp_term2=fix(terms[1]), tp_term3=fix(terms[2]),
                 tp_act=fix(acts[0]), tp_act2=fix(acts[1]),
                 tp_win=fix(wins[int(rng.integers(len(wins)))]),
                 tp_win_cap="",
                 tp_pain=fix(pains[pi]), tp_pain2=fix(pains[(pi + 1 + int(rng.integers(len(pains) - 1))) % len(pains)]),
                 tp_tag=re.sub(r"[^a-z0-9]", "", re.sub(r"^(a|an|the|our|my) ", "", fix(obj).lower()))[:20])
        s["tp_win_cap"] = s["tp_win"][0].upper() + s["tp_win"][1:]


def render(kind: str, rng: np.random.Generator, size: int, *,
           ratings: Optional[Sequence] = None, context: Optional[Dict[str, Sequence]] = None) -> np.ndarray:
    """``size`` texts of ``kind`` (a key of the rules above, or ``feedback``)."""
    g = _grammar(rng)
    slots = _slots(rng, size)
    for key, vals in (context or {}).items():
        vals = list(vals)
        for i, s in enumerate(slots):
            v = vals[i] if i < len(vals) else None
            if v is not None and str(v).strip() and str(v).lower() not in ("nan", "none"):
                s[key] = str(v)
    if kind in ("feedback", "churn"):
        _product_slots(rng, slots)
    if kind == "feedback":
        levels = MicrotextGenerator.normalize_ratings(ratings, size, rng)
        symbols = ["feedback_neg" if lvl <= 2 else "feedback_mid" if lvl == 3 else "feedback_pos"
                   for lvl in levels]
    else:
        symbols = [kind] * size
    if kind in ("complaint", "clinical", "discharge"):
        _case_slots(rng, slots)
    if kind == "delivery":
        _home_slots(g, rng, slots)
    if kind == "cancel":
        _booking_slots(g, rng, slots)
    if kind in ("post_title", "post_body", "caption"):
        _topic_slots(rng, slots, (context or {}).get("title") if kind == "post_body" else None)
    if kind == "bio":
        from misata.scenarios import job_titles
        jobs = job_titles(rng, size)
        for i, s in enumerate(slots):
            jg = s.get("job_title") or str(jobs[i])
            s["job_given"] = jg
            s["job_lower"] = " ".join(w if w.isupper() and len(w) > 1 else w.lower() for w in jg.split())
    out = [g.expand(sym, **s) for sym, s in zip(symbols, slots)]
    if kind == "bio":
        out = [_facet_bio(g, rng, s) if rng.random() < 0.55 else o for o, s in zip(out, slots)]
    if kind == "return":
        out = _product_faults(rng, out, slots, 0.35)
    detail = {"churn": "churn_detail", "cancel": "cancel_detail", "return": "return_detail",
              "delivery": "delivery_detail", "discharge": "discharge_detail", "audit": "audit_detail"}.get(kind)
    if detail:
        p = {"discharge": 0.6, "churn": 0.65, "return": 0.6}.get(kind, 0.85)
        p2 = 0.4 if p > 0.7 else 0.25
        def _two(o, s):
            a = g.expand(detail, **s) if rng.random() < p else ""
            b = g.expand(detail, **s) if rng.random() < p2 else ""
            return o + a + (b if b[:14] != a[:14] else "")
        out = [_two(o, s) for o, s in zip(out, slots)]
    sign = {"note": "note_sign", "clinical": "clin_sign", "discharge": "dis_sign"}.get(kind)
    if sign:
        p_sign = 0.45 if kind == "note" else 0.3
        out = [o + (g.expand(sign, **s) if rng.random() < p_sign else "") for o, s in zip(out, slots)]
    frame = {"churn": "reason_frame", "cancel": "booking_frame", "return": "return_frame",
             "audit": "audit_frame", "delivery": "delivery_frame"}.get(kind)
    if frame:
        out = [(g.expand(frame, **dict(s, text=o[0].lower() + o[1:])) if rng.random() < 0.35 else o)
               for o, s in zip(out, slots)]
    out = [_TIDY_COMMA.sub(",", _TIDY_SPACE.sub(" ", o)).strip() for o in out]
    reg = "casual" if kind == "feedback" else _REGISTER.get(kind)
    if kind in ("post_title", "email_subject", "caption", "complaint"):
        out = vary(out, rng, reg or "casual", rate=0.5, short=True) if reg else out
    elif kind == "bio":
        # the job title is the row's own value: never paraphrase inside it
        out = vary_keeping(out, [(sl.get("job_given", ""), sl.get("city", ""), sl.get("city2", ""),
                                  sl.get("company", "")) for sl in slots], rng, reg, styles=False)
    elif reg:
        sentences = kind in ("feedback", "note", "clinical")
        out = vary(out, rng, reg, styles=sentences)
        # "twice a day." swapped to "b.i.d." must not end in two stops
        out = [_DOUBLE_STOP.sub("", o) for o in out]
    return np.array(out, dtype=object)


def _extend_profiles() -> None:
    from misata import text_profiles as tp
    _CASES.extend(tp.CASES)
    _HOMES.extend(tp.HOMES)
    _BOOKINGS.extend(tp.BOOKINGS)
    _PRODUCTS.extend(tp.PRODUCTS)


_extend_profiles()
